const workflowHelp = "Start a workflow: a script that orchestrates many workers deterministically, in one box, as a child session. Workflows run in the background: this returns at once, and the run's end reaches the starter as a reply. Any session may start one unless the owner's workflow settings say otherwise (dyna_workflows). Use the dyna-workflows skill to write the script, and fan out wide: hundreds of workers are fine, and the box queues what it cannot run at once.\n\nEvery script must begin with `export const meta = {...}`: a PURE LITERAL (no variables, calls or interpolation) giving the workflow's `name`, `profiles` (the profiles agent() may use, the first its default), and optionally `description`, `size`, `repo`, `gpu` (GiB of GPU memory for the run's box, as on session start; a worker has none) and `host` (pin the run's box to a named host). Optional `host` and `sameHost` on the request pin the run's box as on session start (choose only one; request wins over `meta.host`; `sameHost` places it on the parent's host — caller's, or root's when started by the owner). Pass the script inline via `script`; it is plain JavaScript, not TypeScript. `args` is JSON text, and the script reads it parsed as the global `args`.\n\nThe canonical multi-stage pattern — pipeline by default, each dimension verifies as soon as its review completes:\n  export const meta = {\n    name: 'review-changes',\n    profiles: ['<profile>'],\n    description: 'Review changed files across dimensions, verify each finding',\n  }\n  const DIMENSIONS = [{key: 'bugs', prompt: '...'}, {key: 'perf', prompt: '...'}]\n  const results = await pipeline(\n    DIMENSIONS,\n    d => agent(d.prompt, {label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA}),\n    review => parallel(review.findings.map(f => () =>\n      agent(`Adversarially verify: ${f.title}`, {label: `verify:${f.file}`, phase: 'Verify', schema: VERDICT_SCHEMA})\n        .then(v => ({...f, verdict: v}))\n    ))\n  )\n  const confirmed = results.flat().filter(f => !f.failed).filter(f => f.verdict?.isReal)\n  return { confirmed }\n  // Dimension 'bugs' findings verify while dimension 'perf' is still reviewing. No wasted wall-clock.\n\nGlobals: agent(prompt, {profile, schema, label, phase, lane, timeout, worktree}), run(command, {cwd, env, timeout, check, label, phase, lane}), parallel(thunks), pipeline(items, ...stages), merge(results, {base}), workflow(path, args), post(to, text, data, {lane}), phase(title), status(text), log(...) and serve(handler), which only a workflow subscription's script may call. post() reaches the run's parent alone, so to is parent or its name. phase is a step's stage and lane the subject it is about, such as lane: g.id; the run page draws each lane's path through the phases. status(text) sets the run's one-line status under its name on the run page and in the Runs list; it is not a step. resume names an ended run, whose finished steps with unchanged keys return their stored results and whose host pin is kept unless a new host, sameHost or meta.host is given; reload changes a running one. Post data stays separate from text, and large post data and final results reach agents as file attachments. The dyna-workflows skill gives encoding and delivery thresholds, every call's return and failure, concurrency, resume, worktrees and what a worker knows."

const workflowReloadHelp = "Give a running workflow run a new script. The session that started it, a session above that one and the owner reload it. The run's session stops the old script and runs the new one in the same box, on the same branches and journal: a call whose step key finished returns its stored result, one whose step is still running waits for that step's worker, and a new key starts. Running steps the new script does not call run on until the run ends. meta must keep the run's name, repo, size, gpu and host; profiles and description may change. Reload is for a live run; resume, on run, starts a new run from an ended one."

var methodRows = buildMethodRows(methodTable)

func buildMethodRows(rows []MethodEntry) map[contract.Method]MethodEntry {
	result := make(map[contract.Method]MethodEntry, len(rows))
	for _, row := range rows {
		result[row.Method] = row
	}
	return result
}

// Methods returns the one method table: exactly one row per Method constant,
// in method order. Rows without actions are engine-only or not yet served.
// Callers must not modify the table.
func Methods() []MethodEntry { return methodTable }

const historyHelp = "Read the posts of one conversation in time order: any room's feed (omit room for yours), or with dm the owner's DM with that session, in your own room only; another room's DM is refused; every DM and steer of your room's sessions is readable by any session of the room. around (a post id) centres the page on that post and takes its room and conversation; otherwise it shows the newest. Text over 800 characters is cut; pass the post id as post to read it whole. Another room's text comes wrapped in <outside>. Pass older as before or newer as after to page; limit is at most 50."

const transcriptHelp = "Read a session's turns, newest first: each turn's inputs, posts and final text, and one line per tool call. Only sessions of your own room, yours included: session is a name in your room or an ID of one; another room's transcript is refused. turn reads one turn. Text over 800 characters is cut; pass turn with item (an id from cut), and offset for the rest, to read it whole. Pass next as before for older turns; limit is at most 5."
